def combine(n, k):
    res = []
    cur = []

    def go(start):
        if len(cur) == k:
            res.append(cur[:])
            return
        for v in range(start, n - (k - len(cur)) + 2):
            cur.append(v)
            go(v + 1)
            cur.pop()

    go(1)
    return res
